m3_create_collection_draft.definition:
CREATE OR REPLACE FUNCTION public.m3_create_collection_draft(target_id uuid, module_title text, target_path uuid, module_difficulty text, passage_drafts jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; position integer := 0;
begin
  if coalesce(public.m3_current_role(), '') not in ('admin', 'teacher') then raise exception 'Admin or approved Teacher access required'; end if;
  if target_id is null or nullif(btrim(module_title), '') is null then raise exception 'Module ID and title are required'; end if;
  if not exists (select 1 from public.learning_paths where id = target_path) then raise exception 'Select a valid learning path'; end if;
  if module_difficulty is null or module_difficulty not in ('Easy', 'Medium', 'Hard') then raise exception 'Select a valid difficulty'; end if;
  if passage_drafts is null or jsonb_typeof(passage_drafts) <> 'array' then raise exception 'Passages must be an array'; end if;
  -- No automatic publication. Blank passage drafts and empty question banks are valid.
  insert into public.modules(id, title, path_id, difficulty, status, created_by, passage)
  values (target_id, btrim(module_title), target_path, module_difficulty, 'draft', auth.uid(),
    case when jsonb_array_length(passage_drafts) = 1 then passage_drafts->0->>'passageText' else null end);
  insert into public.m3_pending_collection_delivery(module_id) values (target_id);
  for item in select value from jsonb_array_elements(passage_drafts) loop
    position := position + 1;
    if jsonb_typeof(item) <> 'object' or nullif(item->>'id', '') is null
      or jsonb_typeof(item->'title') is distinct from 'string'
      or jsonb_typeof(item->'passageText') is distinct from 'string' then
      raise exception 'Passage % has invalid identity or content', position;
    end if;
    insert into public.module_passages(id, module_id, title, passage_text, display_order, source_material_id)
    values ((item->>'id')::uuid, target_id, btrim(item->>'title'), btrim(item->>'passageText'), position,
      nullif(item->>'sourceMaterialId', '')::uuid);
  end loop;
  return target_id;
end;
$function$

m3_delete_module.definition:
CREATE OR REPLACE FUNCTION public.m3_delete_module(target_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$

declare m public.modules%rowtype; preserve boolean;

begin

  if auth.uid() is null or not public.m3_can_manage_module(target_id) then

    raise exception using errcode='42501', message='Only the module owner or an Admin can delete this reading module';

  end if;

  -- Teachers never hard-delete: their Delete moves the module to the Trash (m3_trash_module).

  if public.m3_current_role() = 'teacher' then

    raise exception using errcode='42501', message='Teachers move reading modules to the Trash; permanent deletion is not available to Teachers';

  end if;

  select * into m from public.modules where id=target_id for update;

  if not found then raise exception 'Reading module not found; refresh the list'; end if;

  if m.deleted_at is not null then return 'soft'; end if;

  -- Lock all owned records before checking incoming references. Concurrent FK

  -- inserts cannot acquire key-share locks until this operation commits.

  perform id from public.module_passages where module_id=target_id order by id for update;

  perform id from public.comprehension_questions where module_id=target_id order by id for update;

  perform a.question_id from public.comprehension_question_answers a join public.comprehension_questions q on q.id=a.question_id

    where q.module_id=target_id order by a.question_id for update of a;

  preserve:=public.m3_deletion_has_history(target_id);

  insert into public.m3_deletion_context values(target_id,txid_current());

  if not preserve then

    begin

      -- Shared uploaded_materials, their Storage files and material-scoped sets

      -- are independent uploader-owned sources, never owned by this module.

      delete from public.comprehension_question_answers where question_id in

        (select id from public.comprehension_questions where module_id=target_id);

      delete from public.comprehension_questions where module_id=target_id;

      delete from public.module_passages where module_id=target_id;

      delete from public.m3_pending_collection_delivery where module_id=target_id;

      delete from public.modules where id=target_id;

    exception when foreign_key_violation then

      -- Whole subtransaction rolls back, including all owned child deletions.

      preserve:=true;

    end;

  end if;

  if preserve then

    update public.modules set deleted_at=clock_timestamp() where id=target_id;

  end if;

  delete from public.m3_deletion_context where module_id=target_id;

  return case when preserve then 'soft' else 'permanent' end;

end; $function$

m3_trash_manager.definition:
CREATE OR REPLACE FUNCTION public.m3_trash_manager(target_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if public.m3_current_role() = 'admin' then return 'admin'; end if;
  -- m3_current_role() is 'teacher' only for an APPROVED Teacher; m3_can_manage_module checks created_by = auth.uid().
  if auth.uid() is not null and public.m3_current_role() = 'teacher' then
    if public.m3_can_manage_module(target_id) then return 'teacher'; end if;
    raise exception using errcode = '42501', message = 'Only the module owner or an Admin can manage this reading module in the Trash';
  end if;
  perform public.m3_require_admin();  -- everyone else: the unchanged Admin refusal
  return 'admin';
end $function$

m3_revise_module.definition:
CREATE OR REPLACE FUNCTION public.m3_revise_module(source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  source public.modules%rowtype;
  open_revision uuid;
  new_id uuid := gen_random_uuid();
  root uuid;
  next_number integer;
  p record;
  q record;
  passage_map jsonb := '{}'::jsonb;
  new_passage uuid;
  new_question uuid;
begin
  if auth.uid() is null or public.m3_current_role() is distinct from 'admin' then
    raise exception using errcode = '42501', message = 'Admin access is required to revise reading modules';
  end if;
  -- FOR SHARE: the original cannot change or be deleted while it is copied.
  select * into source from public.modules where id = source_id for share;
  if not found then raise exception 'Reading module not found; refresh the list'; end if;
  if source.deleted_at is not null then
    raise exception using errcode = '22023', message = 'Restore this module from the Trash before revising it';
  end if;
  if source.published_at is null then
    raise exception using errcode = '22023', message = 'Only published modules are revised; edit the draft directly';
  end if;
  select id into open_revision from public.modules
    where revision_of = source_id and status = 'draft' and deleted_at is null;
  if open_revision is not null then return open_revision; end if; -- continue the existing draft

  perform 1 from public.module_passages where module_id = source_id for share;
  perform 1 from public.comprehension_questions where module_id = source_id for share;
  root := coalesce(source.revision_root, source.id);
  perform 1 from public.modules where id = root for update; -- serializes numbering within a family
  select coalesce(max(revision_number), 1) + 1 into next_number from public.modules where revision_root = root;

  perform set_config('m3.revise_module', source_id::text, true);
  insert into public.modules(id, title, path_id, difficulty, status, created_by, passage, source_material_id,
                             revision_of, revision_root, revision_number)
  values (new_id, source.title, source.path_id, source.difficulty, 'draft', auth.uid(), source.passage,
          source.source_material_id, source_id, root, next_number);
  perform set_config('m3.revise_module', '', true);
  insert into public.m3_pending_collection_delivery(module_id) values (new_id) on conflict do nothing;

  for p in select * from public.module_passages where module_id = source_id order by display_order loop
    new_passage := gen_random_uuid();
    passage_map := passage_map || jsonb_build_object(p.id::text, new_passage);
    insert into public.module_passages(id, module_id, title, passage_text, display_order, source_material_id)
    values (new_passage, new_id, p.title, p.passage_text, p.display_order, p.source_material_id);
  end loop;

  for q in select cq.*, a.correct_answer, a.answer_explanation, a.supporting_evidence
           from public.comprehension_questions cq
           left join public.comprehension_question_answers a on a.question_id = cq.id
           where cq.module_id = source_id and cq.material_id is null
           order by cq.display_order loop
    new_question := gen_random_uuid();
    insert into public.comprehension_questions(id, module_id, passage_id, question_type, question_text, options,
      scaffolding_hint, display_order, generated_by_ai, review_status)
    values (new_question, new_id, (passage_map->>(q.passage_id::text))::uuid, q.question_type, q.question_text,
      q.options, q.scaffolding_hint, q.display_order, q.generated_by_ai, 'generated');
    if q.correct_answer is not null then
      insert into public.comprehension_question_answers(question_id, correct_answer, answer_explanation, supporting_evidence)
      values (new_question, q.correct_answer, q.answer_explanation, q.supporting_evidence);
    end if;
  end loop;
  return new_id;
end $function$

m3_write_material_question_set.definition:
CREATE OR REPLACE FUNCTION public.m3_write_material_question_set(actor_id uuid, target_material uuid, target_set uuid, operation text, expected_revision integer, bank jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  actor_role text;
  owner_id uuid;
  next_number integer;
  saved_set public.material_question_sets%rowtype;
  item jsonb;
  old_question public.comprehension_questions%rowtype;
  answer_text text;
  answer_index integer;
  explanation_text text;
  evidence_text text;
  inserted_question_id uuid;
  position integer := 0;
BEGIN
  SELECT role
  INTO actor_role
  FROM public.profiles
  WHERE id = actor_id;

  IF actor_role IS NULL
    OR actor_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION
      'Question management requires a Teacher or Admin'
      USING ERRCODE = '42501';
  END IF;

  SELECT uploaded_by, next_question_set_number
  INTO owner_id, next_number
  FROM public.uploaded_materials
  WHERE id = target_material
  FOR UPDATE;

  IF NOT FOUND
    OR (actor_role <> 'admin' AND owner_id <> actor_id) THEN
    RAISE EXCEPTION
      'Material unavailable to this account'
      USING ERRCODE = '42501';
  END IF;

  IF operation IS NULL
    OR operation NOT IN ('create', 'regenerate', 'review', 'delete') THEN
    RAISE EXCEPTION
      'Invalid question set operation'
      USING ERRCODE = '22023';
  END IF;

  IF operation <> 'review'
    AND (actor_role <> 'teacher' OR owner_id <> actor_id) THEN
    RAISE EXCEPTION
      'Only the owning Teacher may generate or delete sets'
      USING ERRCODE = '42501';
  END IF;

  IF operation <> 'delete' THEN
    IF jsonb_typeof(bank) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION
        'A question bank is required'
        USING ERRCODE = '22023';
    END IF;

    IF jsonb_array_length(bank) NOT IN (3, 6, 9, 12)
      OR EXISTS (
        SELECT 1
        FROM unnest(
          ARRAY['literal', 'inferential', 'critical']
        ) AS category
        WHERE (
          SELECT count(*)
          FROM jsonb_array_elements(bank) AS q
          WHERE q->>'type' = category
        ) <> jsonb_array_length(bank) / 3
      ) THEN
      RAISE EXCEPTION
        'Choose 3, 6, 9 or 12 questions, evenly divided across the three categories'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF operation = 'create' THEN
    IF target_set IS NOT NULL THEN
      RAISE EXCEPTION
        'New sets must not target an existing set'
        USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.material_question_sets (
      material_id,
      created_by,
      name,
      sequence_number
    )
    VALUES (
      target_material,
      actor_id,
      'Question Set ' || next_number,
      next_number
    )
    RETURNING * INTO saved_set;

    UPDATE public.uploaded_materials
    SET next_question_set_number = next_number + 1
    WHERE id = target_material;
  ELSE
    SELECT *
    INTO saved_set
    FROM public.material_question_sets
    WHERE id = target_set
      AND material_id = target_material
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'Question set not found'
        USING ERRCODE = 'P0002';
    END IF;

    IF expected_revision IS DISTINCT FROM saved_set.revision THEN
      RAISE EXCEPTION
        'This question set changed. Reload it before saving or regenerating.'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  IF operation = 'delete' THEN
    DELETE FROM public.comprehension_question_answers
    WHERE question_id IN (
      SELECT id
      FROM public.comprehension_questions
      WHERE question_set_id = saved_set.id
        AND material_id = target_material
    );

    DELETE FROM public.comprehension_questions
    WHERE question_set_id = saved_set.id
      AND material_id = target_material;

    DELETE FROM public.material_question_sets
    WHERE id = saved_set.id
      AND material_id = target_material;

    RETURN saved_set.id;
  END IF;

  IF operation = 'regenerate'
    AND (
      SELECT count(*)
      FROM public.comprehension_questions
      WHERE question_set_id = saved_set.id
    ) <> jsonb_array_length(bank) THEN
    RAISE EXCEPTION
      'Regeneration must preserve the saved question count'
      USING ERRCODE = '22023';
  END IF;

  IF operation = 'review' THEN
    IF (
      SELECT count(*)
      FROM public.comprehension_questions
      WHERE question_set_id = saved_set.id
    ) <> jsonb_array_length(bank)
    OR (
      SELECT count(DISTINCT q->>'id')
      FROM jsonb_array_elements(bank) AS q
    ) <> jsonb_array_length(bank)
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(bank) AS submitted
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.comprehension_questions AS q
        WHERE q.id = (submitted->>'id')::uuid
          AND q.material_id = target_material
          AND q.question_set_id = saved_set.id
      )
    ) THEN
      RAISE EXCEPTION
        'Every edited question must belong to the selected set'
        USING ERRCODE = '42501';
    END IF;
  ELSIF operation = 'regenerate' THEN
    DELETE FROM public.comprehension_question_answers
    WHERE question_id IN (
      SELECT id
      FROM public.comprehension_questions
      WHERE question_set_id = saved_set.id
        AND material_id = target_material
    );

    DELETE FROM public.comprehension_questions
    WHERE question_set_id = saved_set.id
      AND material_id = target_material;
  END IF;

  FOR item IN
    SELECT value
    FROM jsonb_array_elements(bank)
  LOOP
    position := position + 1;

    explanation_text := NULL;
    evidence_text := NULL;

    IF item ? 'answerExplanation' THEN
      IF jsonb_typeof(item->'answerExplanation')
        IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION
          'Answer explanation must be text'
          USING ERRCODE = '22023';
      END IF;

      explanation_text :=
        nullif(btrim(item->>'answerExplanation'), '');

      IF explanation_text IS NULL
        OR length(explanation_text) > 1500 THEN
        RAISE EXCEPTION
          'Answer explanation must contain 1 to 1500 characters'
          USING ERRCODE = '22023';
      END IF;
    END IF;

    IF item ? 'supportingEvidence' THEN
      IF jsonb_typeof(item->'supportingEvidence')
        IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION
          'Supporting evidence must be text'
          USING ERRCODE = '22023';
      END IF;

      evidence_text :=
        nullif(btrim(item->>'supportingEvidence'), '');

      IF evidence_text IS NULL
        OR length(evidence_text) > 1000 THEN
        RAISE EXCEPTION
          'Supporting evidence must contain 1 to 1000 characters'
          USING ERRCODE = '22023';
      END IF;
    END IF;

    IF operation = 'review' THEN
      SELECT *
      INTO STRICT old_question
      FROM public.comprehension_questions
      WHERE id = (item->>'id')::uuid
        AND question_set_id = saved_set.id;

      SELECT correct_answer
      INTO answer_text
      FROM public.comprehension_question_answers
      WHERE question_id = old_question.id;

      answer_index := NULL;

      SELECT ordinality::integer - 1
      INTO answer_index
      FROM jsonb_array_elements_text(
        old_question.options
      ) WITH ORDINALITY
      WHERE value = answer_text;

      IF answer_index IS NULL THEN
        RAISE EXCEPTION
          'Invalid saved answer key'
          USING ERRCODE = '22023';
      END IF;

      UPDATE public.comprehension_questions
      SET
        question_type = item->>'type',
        question_text = btrim(item->>'questionText'),
        options = item->'options',
        scaffolding_hint = btrim(item->>'scaffoldingHint'),
        review_status = 'reviewed',
        reviewed_by = actor_id,
        reviewed_at = now()
      WHERE id = old_question.id;

      -- Preserve the system-selected correct option.
      -- Preserve feedback when the review request omits it.
      UPDATE public.comprehension_question_answers
      SET
        correct_answer = item->'options'->>answer_index,
        answer_explanation = CASE
          WHEN item ? 'answerExplanation'
            THEN explanation_text
          ELSE answer_explanation
        END,
        supporting_evidence = CASE
          WHEN item ? 'supportingEvidence'
            THEN evidence_text
          ELSE supporting_evidence
        END
      WHERE question_id = old_question.id;
    ELSE
      INSERT INTO public.comprehension_questions (
        material_id,
        question_set_id,
        question_type,
        question_text,
        options,
        scaffolding_hint,
        display_order,
        generated_by_ai,
        review_status
      )
      VALUES (
        target_material,
        saved_set.id,
        item->>'type',
        btrim(item->>'questionText'),
        item->'options',
        btrim(item->>'scaffoldingHint'),
        position,
        true,
        'generated'
      )
      RETURNING id INTO inserted_question_id;

      INSERT INTO public.comprehension_question_answers (
        question_id,
        correct_answer,
        answer_explanation,
        supporting_evidence
      )
      VALUES (
        inserted_question_id,
        item->>'correctAnswer',
        explanation_text,
        evidence_text
      );
    END IF;
  END LOOP;

  UPDATE public.material_question_sets
  SET
    revision = revision + 1,
    updated_at = now()
  WHERE id = saved_set.id;

  RETURN saved_set.id;
END;
$function$
